boilerplate.baseCss:
body {
  margin: 0;
  padding-block: var(--nys-space-300);
  color: var(--nys-color-text);
  font-family: var(--nys-font-family-body);
}

h1 {
  margin-block-start: 0;
}

/* Tighter table rows, so a slide with a table fits a 720p screen. */
nys-table {
  --nys-table-padding--cell--y: var(--nys-space-100);
}

/* A number with its sentence. NYSDS has no stat component, and the
   number isn't a heading, so it stays inside the paragraph. */
.stat {
  margin: 0;
  padding-inline-start: var(--nys-space-200);
  border-inline-start: var(--nys-border-width-lg) solid var(--nys-color-theme);
}

.stat__value {
  display: block;
  font-family: var(--nys-font-family-display);
  font-size: var(--nys-font-size-display-md);
  font-weight: var(--nys-font-weight-bold);
  line-height: var(--nys-font-lineheight-display-md);
}

/* Before-and-after panels. Each panel's heading says which side it is,
   so the border color is never the only cue. */
.compare {
  box-sizing: border-box;
  height: 100%;
  padding: var(--nys-space-250);
  border: var(--nys-border-width-md) solid var(--nys-color-success);
  border-radius: var(--nys-radius-lg);
}

.compare--before {
  border-style: dashed;
  border-color: var(--nys-color-danger);
}

.compare > :first-child {
  margin-block-start: 0;
}

/* What assistive technology gets from each side. */
.readout {
  margin: var(--nys-space-250) 0 0;
  padding: var(--nys-space-150) var(--nys-space-200);
  border-radius: var(--nys-radius-md);
  background: var(--nys-color-base-weak);
  font-family: var(--nys-font-family-ui);
  font-size: var(--nys-font-size-ui-md);
  line-height: var(--nys-font-lineheight-ui-md);
}

.readout dt {
  font-weight: var(--nys-font-weight-semibold);
}

.readout dd {
  margin: 0 0 var(--nys-space-100);
}

.readout dd:last-child {
  margin-block-end: 0;
}

/* Hand-rolled "before" controls share one look, so they match the
   NYSDS side and the only difference is behavior. */
.fake-label {
  display: block;
  margin-block-end: var(--nys-space-100);
  font: var(--nys-font-weight-semibold) var(--nys-font-size-ui-md) / var(--nys-font-lineheight-ui-md) var(--nys-font-family-ui);
}

.fake-input {
  box-sizing: border-box;
  width: 100%;
  padding: var(--nys-space-150);
  border: var(--nys-border-width-sm) solid var(--nys-color-base);
  border-radius: var(--nys-radius-md);
  font: var(--nys-font-size-ui-md) var(--nys-font-family-ui);
}

.fake-button {
  padding: var(--nys-space-150) var(--nys-space-300);
  border: 0;
  border-radius: var(--nys-radius-md);
  background: var(--nys-color-theme);
  color: var(--nys-color-text-reverse);
  font: var(--nys-font-weight-semibold) var(--nys-font-size-ui-md) / var(--nys-font-lineheight-ui-md) var(--nys-font-family-ui);
  cursor: pointer;
}

