presets.js:
// Count the days to each deadline from the day you present, so the
// slide stays right after today.
const DAY = 24 * 60 * 60 * 1000;
const now = new Date();
const today = Date.UTC(now.getFullYear(), now.getMonth(), now.getDate());

document.querySelectorAll('[data-deadline]').forEach((el) => {
  const [year, month, day] = el.dataset.deadline.split('-').map(Number);
  const days = Math.round((Date.UTC(year, month - 1, day) - today) / DAY);
  if (days > 1) {
    el.textContent = `${days} days from today`;
  } else if (days === 1) {
    el.textContent = 'Tomorrow';
  } else if (days === 0) {
    el.textContent = 'Today';
  } else {
    el.textContent = 'In effect';
  }
});

