presets.js:
// Tell keyboard activation from mouse activation, so each log says which.
let lastPointer = 0;
document.addEventListener('pointerdown', () => {
  lastPointer = Date.now();
}, true);
const how = () => (Date.now() - lastPointer < 1000 ? 'the mouse' : 'the keyboard');

const beforeLog = document.getElementById('before-log');
const afterLog = document.getElementById('after-log');

// Before: a div only hears clicks. Tab never lands on it.
document.getElementById('fake-submit').addEventListener('click', () => {
  beforeLog.textContent = `Submit application activated with ${how()}.`;
});
document.getElementById('plain-save').addEventListener('click', () => {
  beforeLog.textContent = `Save draft activated with ${how()}.`;
});

// After: nys-click fires for the mouse and the keyboard alike.
['real-submit', 'real-save'].forEach((id) => {
  const button = document.getElementById(id);
  button.addEventListener('nys-click', () => {
    afterLog.textContent = `${button.getAttribute('label')} activated with ${how()}.`;
  });
});

