presets.js:
// Before: the only feedback is a color change.
const beforeForm = document.getElementById('before-form');
const beforeName = document.getElementById('before-name');
beforeForm.addEventListener('submit', (event) => {
  event.preventDefault();
  beforeName.classList.toggle('is-invalid', beforeName.value.trim() === '');
});

// After: nys-textinput validates itself when the form submits, shows
// the message, and moves focus to the field. This handler runs only
// once the form is valid.
const afterForm = document.getElementById('after-form');
const afterResult = document.getElementById('after-result');
const whatHappens = afterResult.textContent;
afterForm.addEventListener('submit', (event) => {
  event.preventDefault();
  afterResult.textContent = 'The form is valid, so it would submit now.';
});
document.getElementById('after-name').addEventListener('nys-input', () => {
  afterResult.textContent = whatHappens;
});

