presets.js:
// What each token is for, from its NYSDS description.
const USES = {
  '--nys-color-text': 'Primary text. Use it for body copy and headings.',
  '--nys-color-text-weak': 'Secondary text. Use it for metadata, captions, and supporting content.',
  '--nys-color-text-weaker': 'Tertiary text. Use it for subtle labels. Avoid it for important content.',
  '--nys-color-text-weakest': 'Decorative text only. Avoid it for anything people need to read.',
  '--nys-color-link': 'Default link color. Use it for inline links.',
};

const select = document.getElementById('token-select');
const swatch = document.getElementById('swatch');
const sample = document.getElementById('sample');

// WCAG relative luminance and contrast ratio.
const channel = (value) => {
  const c = value / 255;
  return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
};
const luminance = (rgb) => {
  const [r, g, b] = rgb.match(/[\d.]+/g).map(Number);
  return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
};
const contrast = (a, b) => {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
};

const mark = (badge, passes) => {
  badge.setAttribute('intent', passes ? 'success' : 'danger');
  badge.setAttribute('label', passes ? 'Passes' : 'Fails');
  badge.setAttribute('prefixicon', '');
};

function update(token) {
  swatch.style.setProperty('--sample-color', `var(${token})`);
  const ratio = contrast(
    getComputedStyle(sample).color,
    getComputedStyle(swatch).backgroundColor,
  );
  const body = ratio >= 4.5;
  const large = ratio >= 3;
  document.getElementById('token-use').textContent = USES[token];
  document.getElementById('result').textContent =
    `Contrast ratio: ${ratio.toFixed(2)} to 1. ` +
    (body ? 'Passes for all text.' : large ? 'Passes for large text only.' : 'Fails for all text.');
  mark(document.getElementById('body-badge'), body);
  mark(document.getElementById('large-badge'), large);
}

select.addEventListener('nys-change', (event) => update(event.detail.value));
update('--nys-color-text');

presets.css:
/* Before: hand-rolled. Three 16-pixel buttons, 2 pixels apart. */
.tiny-row {
  display: flex;
  gap: var(--nys-space-2px);
}

.tiny {
  position: relative;
  display: grid;
  place-items: center;
  width: var(--nys-size-200);
  height: var(--nys-size-200);
  padding: 0;
  border: 0;
  background: none;
  color: var(--nys-color-ink);
  cursor: pointer;
}

/* The 24-pixel circle WCAG centers on each target. A target smaller
   than 24 pixels passes only if its circle touches no other target
   or circle. */
.show-zones .tiny::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: var(--nys-size-300);
  height: var(--nys-size-300);
  border: var(--nys-border-width-sm) dashed var(--nys-color-danger);
  border-radius: var(--nys-radius-round);
  transform: translate(-50%, -50%);
  pointer-events: none;
}

