presets.js:
// Before: a click toggles the panel. There's no keyboard support, no
// role, and no state for assistive technology to read.
document.querySelectorAll('.fake-accordion__header').forEach((header) => {
  header.addEventListener('click', () => {
    const panel = document.getElementById(header.dataset.panel);
    panel.hidden = !panel.hidden;
  });
});

presets.css:
/* Each fragment stands in for a page, so it gets a frame of its own. */
.fragment {
  padding: var(--nys-space-200);
  border: var(--nys-border-width-sm) solid var(--nys-color-base);
  border-radius: var(--nys-radius-md);
}

.fragment > * {
  margin-block: 0 var(--nys-space-100);
}

.fragment > :last-child {
  margin-block-end: 0;
}

.readout h3 {
  margin: 0 0 var(--nys-space-50);
  font-weight: var(--nys-font-weight-semibold);
}

.readout ul {
  margin: 0;
  padding-inline-start: var(--nys-space-300);
}

.readout li {
  margin: 0;
}

presets.js:
// Build the lists a screen reader offers for skimming a page.
function list(id, items, empty) {
  const ul = document.getElementById(id);
  ul.replaceChildren(...(items.length ? items : [empty]).map((text) => {
    const li = document.createElement('li');
    li.textContent = text;
    return li;
  }));
}

['before', 'after'].forEach((side) => {
  const fragment = document.getElementById(`${side}-fragment`);
  const headings = [...fragment.querySelectorAll('h1, h2, h3, h4, h5, h6')];
  const links = [...fragment.querySelectorAll('a[href]')];
  list(
    `${side}-headings`,
    headings.map((h) => `Level ${h.tagName[1]}: ${h.textContent.trim()}`),
    'No headings',
  );
  list(
    `${side}-links`,
    links.map((a) => a.textContent.trim()),
    'No links',
  );
});

